async function generateNextPaymentReferenceNumber(database2) {
  try {
    const result = await database2.select({ payNum: payments.referenceNumber }).from(payments).orderBy(desc9(payments.referenceNumber)).limit(1);
    let maxSequence = 0;
    if (result && result.length > 0 && result[0].payNum) {
      const match = result[0].payNum.match(/(\d+)$/);
      if (match) {
        maxSequence = parseInt(match[1]);
      }
    }
    const nextSequence = maxSequence + 1;
    return `PAY-${String(nextSequence).padStart(6, "0")}`;
  } catch (err) {
    console.warn("Error generating payment reference number, using default:", err);
    return `PAY-000001`;
  }
}
function normalizeDateValue(value) {
  if (value === void 0 || value === null || value === "") {
    return null;
  }
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value;
  }
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) return null;
    const parsed = new Date(trimmed);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  }
  if (typeof value === "number") {
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  }
  return null;
}
function convertToMySQLDateTime(date2) {
  const normalized2 = normalizeDateValue(date2);
  if (!normalized2) return void 0;
  return normalized2.toISOString().replace("T", " ").substring(0, 19);
}
