// shared/invoiceCarryForward.ts
function isCarryForwardBalanceInvoice(invoice) {
  if (!invoice) return false;
  const title = typeof invoice.title === "string" ? invoice.title.trim() : "";
  const notes2 = typeof invoice.notes === "string" ? invoice.notes.trim() : "";
  const invoiceNumber = typeof invoice.invoiceNumber === "string" ? invoice.invoiceNumber : "";
  return title.toLowerCase().startsWith("balance for ") || notes2.toLowerCase().includes("remaining balance carried forward from invoice") || /^balance for /i.test(invoiceNumber);
}
function filterCarryForwardInvoices(items) {
  return (items ?? []).filter((item) => !isCarryForwardBalanceInvoice(item));
}

