async function fetchFinancialData(config) {
  const db2 = await getDb();
  if (!db2) {
    throw new Error("Database connection not available");
  }
  try {
    let invoicesQuery = db2.select().from(invoices);
    let expensesQuery = db2.select().from(expenses);
    if (config.startDate) {
      const startDateStr = config.startDate instanceof Date ? config.startDate.toISOString().split("T")[0] : config.startDate;
      invoicesQuery = invoicesQuery.where(gte16(invoices.issueDate, startDateStr));
      expensesQuery = expensesQuery.where(gte16(expenses.expenseDate, startDateStr));
    }
    if (config.endDate) {
      const endDateStr = config.endDate instanceof Date ? config.endDate.toISOString().split("T")[0] : config.endDate;
      invoicesQuery = invoicesQuery.where(lte16(invoices.issueDate, endDateStr));
      expensesQuery = expensesQuery.where(lte16(expenses.expenseDate, endDateStr));
    }
    const invoiceData = await invoicesQuery;
    const expenseData = await expensesQuery;
    const totalInvoiced = invoiceData.reduce((sum7, inv) => sum7 + (inv.total || 0), 0);
    const paidInvoices = invoiceData.filter((inv) => inv.status === "paid").reduce((sum7, inv) => sum7 + (inv.total || 0), 0);
    const outstandingAmount = invoiceData.reduce((sum7, inv) => sum7 + ((inv.total || 0) - (inv.paidAmount || 0)), 0);
    const totalExpenses = expenseData.reduce((sum7, exp) => sum7 + (exp.amount || 0), 0);
    const netProfit = totalInvoiced - totalExpenses;
    return {
      invoiceData,
      expenseData,
      totalInvoiced,
      paidInvoices,
      outstandingAmount,
      totalExpenses,
      netProfit
    };
  } catch (error) {
    console.error("Error fetching financial data:", error);
    throw new Error(`Failed to fetch financial data: ${error instanceof Error ? error.message : "Unknown error"}`);
  }
}
