      const fromClause = buildActivityLogFromClause(ctx);
      const [actionRows] = await db2.execute(
        sql39`SELECT action, COUNT(*) as count ${fromClause} ${whereClause} GROUP BY action ORDER BY count DESC LIMIT 10`
      );
