function convertLogsToCSV(logs, companyInfo) {
  const headers = ["ID", "User ID", "Org ID", "Feature", "Action", "Allowed", "Reason", "Timestamp", "IP Address"];
  const rows = logs.map((log) => [
    log.id,
    log.userId,
    log.orgId,
    log.feature,
    log.action,
    log.allowed ? "Yes" : "No",
    log.reason || "",
    log.timestamp,
    log.ipAddress || ""
  ]);
  const companyLines = [
    ["Company", companyInfo.name],
    ["Phone", companyInfo.phone],
    ["Email", companyInfo.email],
    ["Website", companyInfo.website],
    ["Address", companyInfo.address],
    ["Tagline", companyInfo.tagline],
    ["Report", "Permission Audit Logs"],
    []
  ].map((row) => row.map((cell) => `"${String(cell ?? "").replace(/"/g, '""')}"`).join(","));
  const headerLine = headers.join(",");
  const dataLines = rows.map((row) => row.map((cell) => `"${cell}"`).join(","));
  return [...companyLines, headerLine, ...dataLines].join("\n");
}
function getTopFeatures(logs, limit) {
  const features = logs.reduce((acc, log) => {
    const key = String(log.feature ?? "unknown");
    acc[key] = (acc[key] || 0) + 1;
    return acc;
  }, {});
  return Object.entries(features).map(([feature, count10]) => ({ feature, count: Number(count10) })).sort((a, b) => b.count - a.count).slice(0, limit);
}
function getTopUsers(logs, limit) {
  const usersById = logs.reduce((acc, log) => {
    const key = String(log.userId ?? "unknown");
    acc[key] = (acc[key] || 0) + 1;
    return acc;
  }, {});
  return Object.entries(usersById).map(([userId, count10]) => ({ userId, count: Number(count10) })).sort((a, b) => b.count - a.count).slice(0, limit);
}

