function staffPayslipValues(payslip) {
  const normalizedPayslip = payslipAmounts(payslip);
  const grossSalary = normalizedPayslip.grossSalary / 100;
  const netSalary = normalizedPayslip.netSalary / 100;
  return {
    ...normalizedPayslip,
    basicSalary: Number(normalizedPayslip.basicSalary || 0) / 100,
    grossSalary,
    grossPay: grossSalary,
    totalDeductions: Number(payslip.totalDeductions || 0) / 100,
    netSalary,
    netPay: netSalary
  };
}
function isPayslipManager(user) {
  const normalizedRoles = [user.role, user.effectiveRole].map(
    (role) => String(role || "").trim().toLowerCase().replace(/[\s-]+/g, "_")
  );
  return normalizedRoles.some(
    (role) => ["admin", "super_admin", "superadmin", "hr", "hr_manager"].includes(role)
  );
}
function isGlobalSuperAdmin(user) {
  return [user.role, user.effectiveRole].some(
    (role) => ["super_admin", "superadmin"].includes(String(role || "").trim().toLowerCase().replace(/[\s-]+/g, "_"))
  );
}
function displayBreakdown(value) {
  return parseBreakdown2(value).map((item) => ({
    ...item,
    amount: Number(item.amount ?? item.cost ?? 0) / 100,
    ...item.cost === void 0 ? {} : { cost: Number(item.cost) / 100 }
  }));
}
