init_db();
import crypto2 from "node:crypto";
function signature(secret, body) {
  return crypto2.createHmac("sha256", secret).update(body).digest("hex");
}
async function processERPIntegrationEvents(limit = 20) {
  const pool13 = getPool();
  if (!pool13) return { processed: 0, succeeded: 0, failed: 0, deadLettered: 0 };
  const [events] = await pool13.query(
    "SELECT * FROM integration_events WHERE status='pending' AND (nextAttemptAt IS NULL OR nextAttemptAt<=NOW()) ORDER BY createdAt LIMIT ?",
    [limit]
  );
  let succeeded = 0;
  let failed = 0;
  let deadLettered = 0;
  for (const event of events) {
    const body = JSON.stringify({ id: event.id, provider: event.provider, eventType: event.eventType, payload: JSON.parse(event.payload || "{}") });
    const [webhooks2] = await pool13.query(
      "SELECT * FROM api_webhooks WHERE organizationId=? AND isActive=1 AND (events LIKE ? OR events LIKE '%*%')",
      [event.organizationId, `%${event.eventType}%`]
    );
    const attemptNumber = Number(event.attempts || 0) + 1;
    await pool13.query("UPDATE integration_events SET status='processing',attempts=? WHERE id=?", [attemptNumber, event.id]);
    let eventSucceeded = webhooks2.length === 0;
    let lastError = "";
    for (const webhook of webhooks2) {
      try {
        const response = await fetch(webhook.url, {
          method: "POST",
          headers: { "content-type": "application/json", "x-Kiini-event": event.eventType, "x-Kiini-signature": signature(webhook.secret || "", body) },
          body
        });
        const responseBody = (await response.text()).slice(0, 4e3);
        await pool13.query("INSERT INTO integration_attempts (id,eventId,attemptNumber,status,responseCode,responseBody) VALUES (?,?,?,?,?,?)", [`attempt_${event.id}_${attemptNumber}_${webhook.id}`, event.id, attemptNumber, response.ok ? "succeeded" : "failed", response.status, responseBody]);
        if (!response.ok) {
          eventSucceeded = false;
          lastError = `Webhook ${webhook.id} returned ${response.status}`;
        }
      } catch (error) {
        eventSucceeded = false;
        lastError = error instanceof Error ? error.message : String(error);
        await pool13.query("INSERT INTO integration_attempts (id,eventId,attemptNumber,status,error) VALUES (?,?,?,?,?)", [`attempt_${event.id}_${attemptNumber}_${webhook.id}`, event.id, attemptNumber, "failed", lastError]);
      }
    }
    if (eventSucceeded) {
      await pool13.query("UPDATE integration_events SET status='succeeded',lastError=NULL WHERE id=?", [event.id]);
      succeeded++;
    } else if (attemptNumber >= 5) {
      await pool13.query("UPDATE integration_events SET status='dead_letter',lastError=? WHERE id=?", [lastError || "No webhook delivery succeeded", event.id]);
      await dispatchSystemAlert({
        title: `Integration delivery failed: ${event.provider}`,
        message: lastError || "The integration event could not be delivered after five attempts.",
        organizationId: event.organizationId,
        category: "integration_failure",
        priority: "critical",
        integrationName: event.provider,
        errorCode: "DEAD_LETTER",
        failedCount: attemptNumber
      });
      deadLettered++;
    } else {
      const delayMinutes = Math.min(60, 2 ** attemptNumber);
      await pool13.query("UPDATE integration_events SET status='pending',lastError=?,nextAttemptAt=DATE_ADD(NOW(), INTERVAL ? MINUTE) WHERE id=?", [lastError, delayMinutes, event.id]);
      failed++;
    }
  }
  return { processed: events.length, succeeded, failed, deadLettered };
}

// server/_core/scheduler.ts
function initializeSchedulers() {
  console.log("[SCHEDULER] Initializing background job schedulers...");
  const emailQueueJob = new CronJob6("*/5 * * * *", async () => {
    try {
      console.log("[SCHEDULER] Running email queue processor...");
      const result = await processEmailQueue2();
      if (result.success) {
        console.log(
          `[SCHEDULER] Email queue processed: ${result.processed} sent, ${result.failed} failed out of ${result.total}`
        );
      } else {
        console.error("[SCHEDULER] Email queue processor failed:", result.error);
      }
    } catch (error) {
      console.error("[SCHEDULER] Error in email queue processor:", error);
    }
  });
  const overdueRemindersJob = new CronJob6("0 9 * * *", async () => {
    try {
      console.log("[SCHEDULER] Running overdue invoice reminder check...");
      const result = await sendOverdueReminders();
      console.log(
        `[SCHEDULER] Overdue reminders processed: ${result.sent} sent, ${result.skipped} skipped, ${result.errors} errors`
      );
    } catch (error) {
      console.error("[SCHEDULER] Error in overdue reminders processor:", error);
    }
  });
  const usageReminderJob = new CronJob6("0 10 * * 1", async () => {
    try {
      console.log("[SCHEDULER] Running usage reminder check...");
      const result = await sendUsageReminders();
      console.log(
        `[SCHEDULER] Usage reminders: ${result.sent} sent, ${result.skipped} skipped, ${result.errors} errors`
      );
    } catch (error) {
      console.error("[SCHEDULER] Error in usage reminders:", error);
    }
  });
  const remindersJob = new CronJob6("*/5 * * * *", async () => {
    try {
      const result = await processDueReminders();
      if (result.processed > 0) console.log(`[SCHEDULER] Reminders: ${result.delivered}/${result.processed} delivered`);
    } catch (error) {
      console.error("[SCHEDULER] Error in reminders processor:", error);
    }
  });
  const weeklySystemReportJob = new CronJob6("0 8 * * 1", async () => {
    try {
      const result = await dispatchSystemReport("weekly");
      console.log(`[SCHEDULER] Weekly system reports delivered: ${result.delivered}`);
    } catch (error) {
      console.error("[SCHEDULER] Error in weekly system reports:", error);
    }
  });
  const monthlySystemReportJob = new CronJob6("0 8 1 * *", async () => {
    try {
      const result = await dispatchSystemReport("monthly");
      console.log(`[SCHEDULER] Monthly system reports delivered: ${result.delivered}`);
    } catch (error) {
      console.error("[SCHEDULER] Error in monthly system reports:", error);
    }
  });
  const erpIntegrationJob = new CronJob6("*/2 * * * *", async () => {
    try {
      const result = await processERPIntegrationEvents();
      if (result.processed > 0) console.log(`[SCHEDULER] ERP integrations: ${result.succeeded} succeeded, ${result.failed} retrying, ${result.deadLettered} dead-lettered`);
    } catch (error) {
      console.error("[SCHEDULER] Error in ERP integration processor:", error);
    }
  });
  emailQueueJob.start();
  overdueRemindersJob.start();
  usageReminderJob.start();
  remindersJob.start();
  weeklySystemReportJob.start();
  monthlySystemReportJob.start();
  erpIntegrationJob.start();
  console.log("[SCHEDULER] Background jobs started:");
  console.log("  - Email queue processor: Every 5 minutes");
  console.log("  - Overdue invoice reminders: Daily at 09:00 AM");
  console.log("  - Usage reminders: Weekly on Monday at 10:00 AM");
  console.log("  - System reports: Weekly Monday 08:00 and monthly 1st at 08:00");
  console.log("  - ERP integration events: Every 2 minutes with bounded retries");
  return {
    emailQueueJob,
    overdueRemindersJob,
    usageReminderJob,
    remindersJob,
    weeklySystemReportJob,
    monthlySystemReportJob,
    erpIntegrationJob
  };
}

